#include <stdio.h>

int main() {
    int data[] = {2, 4, 6, 8, 10};
    int *end = data + sizeof(data) / sizeof(data[0]);
    int total = 0;
    for (int *p = data; p < end; p++) {
        total += *p;
    }
    printf("%d\n", total);
    return 0;
}
